package com.secretalk.backend.service;
import com.secretalk.backend.entity.*; import com.secretalk.backend.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.scheduling.annotation.Scheduled; import java.time.LocalDateTime; import java.util.*;
@Service public class CallHistoryService {
 private final CallHistoryRepository calls; private final UserRepository users;
 public CallHistoryService(CallHistoryRepository c,UserRepository u){calls=c;users=u;}
 @Transactional public void started(String callerName, Long calleeId, String mode){User a=users.findByUsernameIgnoreCase(callerName).orElse(null);User b=users.findById(calleeId).orElse(null);if(a==null||b==null)return;CallHistory c=new CallHistory();c.setCaller(a);c.setCallee(b);c.setMode("video".equalsIgnoreCase(mode)?"video":"audio");c.setOutcome("RINGING");c.setStartedAt(LocalDateTime.now());int days=a.getCallHistoryRetentionDays();c.setExpiresAt(days==0?null:LocalDateTime.now().plusDays(days));calls.save(c);}
 @Transactional public void ended(String username, Long otherId, String outcome){User a=users.findByUsernameIgnoreCase(username).orElse(null);if(a==null)return;List<CallHistory> list=calls.findByCaller_IdOrCallee_IdOrderByStartedAtDesc(a.getId(),a.getId());for(CallHistory c:list){boolean match=(c.getCaller().getId().equals(a.getId())&&c.getCallee().getId().equals(otherId))||(c.getCallee().getId().equals(a.getId())&&c.getCaller().getId().equals(otherId));if(match&&("RINGING".equals(c.getOutcome()) || ("COMPLETED".equals(outcome) && "ANSWERED".equals(c.getOutcome())))){c.setOutcome(outcome);c.setEndedAt(LocalDateTime.now());calls.save(c);break;}}}
 @Transactional public int retentionDays(String username){return users.findByUsernameIgnoreCase(username).orElseThrow().getCallHistoryRetentionDays();}
 @Transactional public int updateRetentionDays(String username,int days){if(days!=1&&days!=7&&days!=30&&days!=90&&days!=0)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Retention must be 1, 7, 30, 90 or 0");User u=users.findByUsernameIgnoreCase(username).orElseThrow();u.setCallHistoryRetentionDays(days);users.save(u);return days;}
 @Transactional(readOnly=true) public List<Map<String,Object>> history(String username){User me=users.findByUsernameIgnoreCase(username).orElseThrow();List<Map<String,Object>> out=new ArrayList<>();for(CallHistory c:calls.findByCaller_IdOrCallee_IdOrderByStartedAtDesc(me.getId(),me.getId())){Map<String,Object> row=new LinkedHashMap<>();row.put("id",c.getId());row.put("username",c.getCaller().getId().equals(me.getId())?c.getCallee().getUsername():c.getCaller().getUsername());row.put("direction",c.getCaller().getId().equals(me.getId())?"outgoing":"incoming");row.put("mode",c.getMode());row.put("outcome",c.getOutcome());row.put("startedAt",c.getStartedAt());row.put("endedAt",c.getEndedAt());out.add(row);}return out;}
 @Transactional @Scheduled(fixedDelay=60000) public void clean(){for(CallHistory c:calls.findByExpiresAtBefore(LocalDateTime.now()))calls.delete(c);}
}
